code.css:
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.toolbar-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(100%, 16rem), 1fr)
  );
  gap: 1rem;
}

.page-title {
  font-size: clamp(1.5rem, 1rem + 2vw, 2.5rem);
}

.page-shell {
  width: min(100% - 2rem, 72rem);
  margin-inline: auto;
}

:root {
  --color-accent: #167d72;
  --color-surface: #f4f7f5;
  --space-3: 0.75rem;
  --radius-control: 0.375rem;
}

.button {
  color: white;
  background: var(--color-accent);
  padding: var(--space-3);
  border-radius: var(--radius-control);
}

.single-line {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.multiline {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.app-shell {
  position: relative;
  isolation: isolate;
}

.page-content {
  position: relative;
  z-index: 0;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-width: 320px;
}

img,
svg,
video {
  display: block;
  max-width: 100%;
}

.page-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 16rem;
  gap: 2rem;
  align-items: start;
}

.sidebar {
  position: sticky;
  top: 1rem;
  max-height: calc(100vh - 2rem);
  overflow: auto;
}

@media (max-width: 48rem) {
  .page-layout {
    grid-template-columns: 1fr;
  }
  .sidebar {
    position: static;
    max-height: none;
  }
}

.card-list {
  container-type: inline-size;
}

.card {
  display: grid;
  gap: 1rem;
}

@container (min-width: 36rem) {
  .card {
    grid-template-columns: 8rem 1fr;
    align-items: center;
  }
}

.panel {
  transition: transform 180ms ease, opacity 180ms ease;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
